"""Подбор вопросов экзамена к главам учебника по темам базы и ключевым словам → content/exam-auto.js"""
import json, re, sys
B = json.load(open(sys.argv[1], encoding='utf-8'))
RULES = {
  8: ([4], r'идеальн|Клапейрон|Менделеев|молекулярно-кинетич|Максвелл|Больцман|барометрич|свободного пробега|диффузи|вязкост|внутреннего трения|теплопроводн|средн\w* квадратичн|концентрац|моль|Авогадро|вакуум|скорост\w* молекул|давлени\w* газа|изотерм\w* процесс|изобар|изохор|Бойл|Гей-Люссак|Шарл|молекул|температур\w* по шкале|кельвин|Плотность газа|объем\w* газа|объём\w* газа|распределени\w* числа молекул|водород'),
  9: ([4], r'термодинамик|теплоемкост|теплоёмкост|адиабат|степен\w* свобод|внутренн\w* энерги|работ\w* газа|Карно|КПД|энтропи|Пуассон|Майер|тепловой машин|холодильн|обратим|цикл|количеств\w* теплоты|теплот|работ\w*.{0,25}газ|полезного действия|двигател|кругов'),
  10: ([4], r'Ван-дер-Ваальс|реальн\w* газ|критическ|поверхностн\w* натяжени|смачива|капилляр|Лаплас|кристалл|фазов|тройн\w* точк|плавлени|испарени|кипени|сублимац|насыщенн\w* пар|Дюлонг|Джоул\w*.Томсон|жидкост|сжать|полимер|аморфн|твердых тел|твёрдых тел'),
  11: ([2], r'Кулон|напряж[её]нност|потенциал|диэлектри|поляриз|Гаусс|Остроградск|конденсатор|[её]мкост|заряд|диполь|эквипотенциал|смещени|сегнетоэлектр|проводник\w* в .{0,20}пол|энерги\w* .{0,20}пол'),
  12: ([2], r'(?<![а-яё])ток|(?<![а-яё])Ом(?![а-яё])|сопротивлени|ЭДС|Кирхгоф|Джоул|мощност|амперметр|вольтметр|резистор|источник\w* тока|проводимост'),
  13: ([2, 8], r'эмисси|работ\w* выхода|газов\w* разряд|плазм|ионизац|разряд|электрон\w* .{0,20}металл|проводимост\w* металл|через металл'),
  14: ([3], r'магнитн\w* пол|индукци\w* магнитн|Био|Савар|Ампер|Лоренц|соленоид|тороид|Холл|циклотрон|магнитн\w* момент|правил\w* буравчик|параллельн\w* проводник|напряж[её]нност\w* магнитн|циркуляц|поток|Эрстед|тесла|проводник'),
  15: ([3], r'электромагнитн\w* индукц|индукционн|Фараде|Ленц|самоиндукц|индуктивност|взаимн\w* индукц|трансформатор|вихрев|Фуко|энерги\w* магнитн|потокосцеплен|ЭДС|рамк|гальванометр|кольц'),
  16: ([3], r'ферромагнет|парамагнет|диамагнет|намагниченност|магнитн\w* проницаемост|гистерезис|Кюри|домен|магнетик'),
  17: ([3, 5], r'Максвелл|ток\w* смещени|вихрев\w* электрическ'),
}
out = {}
for ch, (tops, rx) in RULES.items():
    R = re.compile(rx, re.I)
    ks = [q['key'] for q in B if q['tid'] in tops and R.search(q['q'] + ' ' + str(q['a']))]
    out[ch] = ks
taken = {}
# сначала узкие главы, потом широкие: вопрос достаётся самой специфичной подходящей главе
ORDER = [10, 9, 8, 16, 17, 15, 13, 14, 12, 11]
for ch in ORDER + [c for c in sorted(out) if c not in ORDER]:
    out[ch] = [k for k in out[ch] if k not in taken]; [taken.setdefault(k, ch) for k in out[ch]]
lines = ['/* Вопросы экзамена к главам 8–33: подобраны по темам базы и ключевым словам (tools/exam_auto.py) */']
for ch in sorted(out): lines.append('if (CONTENT[%d] && !CONTENT[%d].exam.length) CONTENT[%d].exam = %s;' % (ch, ch, ch, json.dumps(out[ch])))
open(sys.argv[2], 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
for ch in sorted(out): print(ch, len(out[ch]))
miss = [q['key'] for q in B if q['tid'] == 4 and q['key'] not in taken]; print('topic4 not assigned:', len(miss), miss[:20])
